/// <summary>
/// This method is used to create catalog translation.
/// </summary>
/// <param name="_catalogId">
/// The value of catalog ID.
/// </param>
/// <param name="_friendlyName">
/// Translation friendly name.
/// </param>
/// <param name="_description">
/// Translation description
/// </param>
/// <param name="_image">
/// Translation image.
/// </param>
/// <param name="_languageId">
/// Translation langauge ID.
/// </param>
public static void createTranslation(RefRecId _translationId, Name _translation, LanguageId _languageId = SystemParameters::getSystemLanguageId())
{
    MobTranslationLines translation;

    ttsbegin;

    translation = MobTranslationLines::find(_translationId, _languageId, true);

    if (translation)
    {
        //translation.FriendlyName = _friendlyName;
        //translation.Description = _description;
        //translation.Image = _image;
        translation.Translation = _translation;
        translation.update();
    }
    else
    {
        translation.TranslationHeader = _translationId;
        translation.Translation = _translation;
        //translation.FriendlyName = _friendlyName;
        //translation.Description = _description;
        //translation.Image = _image;
        translation.Language = _languageId;
        translation.insert();
    }

    ttscommit;
}

/// <summary>
/// This method is used to find the catalog transaction.
/// </summary>
/// <param name="_catalogId">
/// The value of catalog ID.
/// </param>
/// <param name="_languageId">
/// The default langauge ID in the language table.
/// </param>
/// <param name="_forUpdate">
/// Boolean value for update.
/// </param>
/// <returns>
/// Catalog transaction entry.
/// </returns>
public static MobTranslationLines find(RefRecId _translationId, LanguageId _languageId = SystemParameters::getSystemLanguageId(), boolean _forUpdate = false)
{
    MobTranslationLines translation = null;
    ;

    //PB: should we add support for fallback langauges. E.g. en_GB -> en?

    if (_translationId && _languageId)
    {
        translation.selectForUpdate(_forUpdate);
        select translation where translation.TranslationHeader== _translationId &&
                                 translation.Language == _languageId;
    }

    return translation;
}
